package com.interview.fraudalert.integration;
import com.interview.fraudalert.event.*; import com.interview.fraudalert.model.RiskLevel; import com.interview.fraudalert.service.FraudDetectionConsumer; import org.junit.jupiter.api.Test; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.beans.factory.annotation.Value; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.kafka.core.KafkaTemplate; import org.springframework.kafka.test.context.EmbeddedKafka; import org.springframework.kafka.test.utils.KafkaTestUtils; import org.springframework.kafka.core.DefaultKafkaConsumerFactory; import org.apache.kafka.clients.consumer.ConsumerConfig; import org.springframework.kafka.support.serializer.JsonDeserializer; import java.math.BigDecimal; import java.time.Duration; import java.time.Instant; import java.util.*; import static org.assertj.core.api.Assertions.assertThat;
@SpringBootTest(properties={"spring.kafka.bootstrap-servers=${spring.embedded.kafka.brokers}","spring.kafka.consumer.auto-offset-reset=earliest"})
@EmbeddedKafka(partitions=1, topics={"transaction.received","fraud.evaluated"})
class FraudFlowIntegrationTest { @Autowired FraudDetectionConsumer consumer; @Autowired KafkaTemplate<String, TransactionReceivedEvent> txTemplate; @Value("${spring.embedded.kafka.brokers}") String brokers;
 @Test void consumerPublishesFraudEvaluation(){ var props=KafkaTestUtils.consumerProps("test-consumer","true",brokers); props.put(ConsumerConfig.AUTO_OFFSET_RESET_CONFIG,"earliest"); JsonDeserializer<FraudEvaluatedEvent> deser=new JsonDeserializer<>(FraudEvaluatedEvent.class,false); deser.addTrustedPackages("com.interview.fraudalert.event"); var cf=new DefaultKafkaConsumerFactory<String,FraudEvaluatedEvent>(props, new org.apache.kafka.common.serialization.StringDeserializer(), deser); var kafkaConsumer=cf.createConsumer(); kafkaConsumer.subscribe(List.of("fraud.evaluated")); consumer.onTransactionReceived(new TransactionReceivedEvent(UUID.randomUUID(),"A1",new BigDecimal("12000"),"M","US", Instant.now())); var records=KafkaTestUtils.getRecords(kafkaConsumer, Duration.ofSeconds(10)); assertThat(records.count()).isGreaterThan(0); assertThat(records.iterator().next().value().riskLevel()).isEqualTo(RiskLevel.HIGH_RISK); kafkaConsumer.close(); }
}
